import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"移除内置业务并保留 SaaS Core","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/example-removal","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/example-removal.md","filePath":"tutorials/example-removal.md"}'),n={name:"tutorials/example-removal.md"};function p(l,a,d,o,h,r){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="移除内置业务并保留-saas-core" tabindex="-1">移除内置业务并保留 SaaS Core <a class="header-anchor" href="#移除内置业务并保留-saas-core" aria-label="Permalink to &quot;移除内置业务并保留 SaaS Core&quot;">​</a></h1><p>从自己的模板工作副本移除知识库业务，让账号、成员、Session、Files、Jobs、通知、审计、邮件、API Key、限流和遥测继续服务自己的 SaaS。Example Removal 改变源码与派生产物，不删除现有生产数据库、对象或密钥。</p><p>前提是干净 Git 工作副本和已安装工具链。命令在仓库根目录运行；先保存自己的改动，或在独立临时副本演练，不在未提交的工作上强行执行。</p><h2 id="先检查所有权与预览" tabindex="-1">先检查所有权与预览 <a class="header-anchor" href="#先检查所有权与预览" aria-label="Permalink to &quot;先检查所有权与预览&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p>默认示例 id 为 <code>knowledge-base</code>。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/example-remove.mjs" target="_blank" rel="noreferrer">工具</a>读取 <code>examples/&lt;id&gt;/manifest.json</code>，列出路径、注册区块、教程导航、独占依赖和再生命令，不写文件。</p><table tabindex="0"><thead><tr><th>清单字段</th><th>作用</th></tr></thead><tbody><tr><td><code>ownedPaths</code></td><td>独占源码、测试、迁移和双语教学页</td></tr><tr><td><code>registrationMarkers</code></td><td>共享组装文件里的成对 <code>example:&lt;prefix&gt;:&lt;marker&gt;:start/end</code></td></tr><tr><td><code>compositionPoints</code></td><td>需要改写而非删除的 API、Worker、Web、文档入口</td></tr><tr><td><code>ownedDependencies</code> / <code>ownedCargoDependencies</code></td><td>只属于该业务的依赖</td></tr><tr><td><code>retainedMigrations</code></td><td>移除代码后保留的历史迁移</td></tr></tbody></table><p>所有权冲突、缺失/重复 marker、未知 id 或未提交改动会阻止实际执行。遇到拒绝，按报告修复归属或保存改动；不要通过关闭保护绕过自己的定制。</p><h2 id="选择迁移历史策略" tabindex="-1">选择迁移历史策略 <a class="header-anchor" href="#选择迁移历史策略" aria-label="Permalink to &quot;选择迁移历史策略&quot;">​</a></h2><p>已应用或发布过迁移的项目使用默认路径：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span></span></code></pre></div><p>业务源码和注册移除，历史迁移保留并登记 <code>retainedMigrations</code>。现有表和数据仍在，应用迁移集合/checksum 也保持一致。需要清理生产数据时另写新增迁移、对象清理与审计方案，不能删除已经执行过的迁移文件。</p><p>从未创建数据库的全新项目可选择：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trim-migrations</span></span></code></pre></div><p>这会裁剪示例迁移，供新空库直接从 Core 初始化。工具不会连接数据库确认是否曾经执行，使用者必须保证这个前提；已有数据库不能采用裁剪路径。</p><h2 id="验证缩减后的应用" tabindex="-1">验证缩减后的应用 <a class="header-anchor" href="#验证缩减后的应用" aria-label="Permalink to &quot;验证缩减后的应用&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-core</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-build</span></span></code></pre></div><p>移除工具会重新生成 lockfile、合同/SDK 与文档参考。检查编译、真实 Core HTTP/任务行为、依赖边界、前端与文档构建；再运行自己的业务测试。</p><p>通用首页、身份入口和设置保留。已移除业务的历史通知仍可读/标记已读，但目标不可用；旧业务链接给出可恢复的不可用反馈，不能把历史记录当作存在的 API。默认业务入口被移除后回到通用首页，直接访问 <code>/</code> 始终是通用首页。</p><p>备份/恢复工具继续运行。参考业务专有的生产 smoke、恢复演练与负载场景会在缺少示例时说明并退出；应替换为自己的业务断言，不能把跳过解释为验收通过。</p><h2 id="增减另一个参考业务" tabindex="-1">增减另一个参考业务 <a class="header-anchor" href="#增减另一个参考业务" aria-label="Permalink to &quot;增减另一个参考业务&quot;">​</a></h2><p>仓库附带只验证 UI 组合合同的便签，默认未注册，没有便签后端。装回和移除都要求干净副本；每次操作后先验证并提交自己的改动，再进行下一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-add.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span></span></code></pre></div><p>未注册的便签缺少必要 marker，不能直接整体移除；先装回再移除，或按清单手工处理。该组合仍属于同一 Organization，见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/adr/0003-static-example-composition.md" target="_blank" rel="noreferrer">源码组合 ADR</a>。</p><h2 id="开始自己的模块" tabindex="-1">开始自己的模块 <a class="header-anchor" href="#开始自己的模块" aria-label="Permalink to &quot;开始自己的模块&quot;">​</a></h2><p>按<a href="./../guides/new-module">新增业务模块</a>接入 Router/OpenAPI，再添加自有 schema、迁移和 <code>module.json</code>；身份、成员、Files、Audit 和 Jobs 使用公共接口。新注册区块应在被移除业务的 marker 外。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/example-new-business.mjs" target="_blank" rel="noreferrer">新业务练习脚本</a>在已移除知识库的副本中创建真实后端便签模块、迁移和 HTTP 测试，验证注册 → 创建 → 读取；这是开发练习，与附带的纯 UI 便签不同。它会修改指定副本并需要 Docker/PostgreSQL，不能在生产工作副本重复执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-new-business.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/my-clean-core-copy</span></span></code></pre></div><p>把 <code>/tmp/my-clean-core-copy</code> 替换为已完成删例的演练副本。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/example-remove.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>工具测试验证精确删除、dry-run、历史迁移、依赖/导航裁剪与拒绝行为。下一步：后端继续<a href="./../guides/new-module">新增模块</a>，需要 Web 页面时再读<a href="./add-example">应用壳贡献</a>。</p><hr><p>源码版本：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/tutorials/23-example-removal.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,34)])])}const g=s(n,[["render",p]]);export{k as __pageData,g as default};
